int main(int argc,char**argv){CHECK(argc==5);CHECK(event_value(WorldDamageEventKind::FlyingNumber,1,-1396.8333740234375,-1396.833374));CHECK(!event_value(WorldDamageEventKind::FlyingNumber,1,-1396.8333740234375,-1395.833374));CHECK(!event_value(WorldDamageEventKind::FlyingNumber,3,.5000000001,.5));CHECK(!event_value(WorldDamageEventKind::Camera,1,.5000000001,.5));CHECK(!event_value(WorldDamageEventKind::FlyingNumber,1,NAN,NAN));std::vector<uint8_t>bytes;CHECK(encore::read_file(argv[1],bytes,1048576,error));PoisonContactsData data;WorldDamageData damage;FieldStepsData steps;CHECK(data.load(bytes.data(),bytes.size(),error)&&damage.load_file(argv[2],error)&&steps.load_file(argv[3],error));parser(bytes,data);original(argv[4],data,damage,steps.view());runtime_negative(data,damage,steps.view());std::cout<<"Poison automatic contact checks: "<<checks<<" passed;105 settled native states,source geometry and real Character/damage;not exact callback-frame/full room/hardware\n";}
